gawk '
BEGIN { FPAT = "([^,]*)|(\"([^\"]|\"\")*\")" }
function csv_decode(f) {
  if (substr(f,1,1) == "\"") {
    f = substr(f, 2, length(f)-2)
    gsub(/""/, "\"", f)
  }
  return f
}
function json_escape(s) {
  gsub(/\\/, "\\\\", s)
  gsub(/"/, "\\\"", s)
  gsub(/\010/, "\\b", s)
  gsub(/\014/, "\\f", s)
  gsub(/\n/, "\\n", s)
  gsub(/\r/, "\\r", s)
  gsub(/\t/, "\\t", s)
  return s
}
NR==1 { for (i=1;i<=NF;i++) h[i]=csv_decode($i); n=NF; next }
{
  # skip empty lines
  if (NF==0) next
  if (NF==1 && $1=="") next
  printf "%s{", (NR>2 ? ",\n" : "[\n")
  for (i=1;i<=n;i++) {
    v = (i<=NF ? csv_decode($i) : "")
    printf "%s\"%s\": \"%s\"", (i>1?", ":""), json_escape(h[i]), json_escape(v)
  }
  printf "}"
}
END { print "\n]" }
' /data/users.csv
